import {GEAR,EXPEDITIONS} from './expedition-data.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reward=r=>`通过${r.cleared}场 · ${r.gold}金币 · 每位出战者${r.xp}经验${r.loot?.length?' · '+r.loot.map(id=>GEAR[id]?.name||id).join('、'):''}`;
export function campCycleView(c){return `<section class="panel camp-cycle" data-cycle-stage="${c.stage}"><p class=eyebrow>营地目标 / 正式出征 → 复盘 → 领取 → 成长 → 再出发</p><h2>${esc(c.title)}</h2><p>${esc(c.text)}</p>${c.last?`<p class=cycle-receipt>最近远征已领取：第${c.last.id}次 · ${esc(EXPEDITIONS[c.last.route].name)} · ${reward(c.last)}</p>`:''}<div class=bar><button class=primary data-cycle-action="${c.primary.action}" data-cycle-value="${c.primary.value}">${esc(c.primary.label)} →</button>${c.heroId&&c.primary.action!=='training'?'<button data-cycle-action=training>我的成长</button>':''}${c.heroId?'<button data-cycle-action=equipment>我的装备</button>':''}${c.stage==='growth'?'<button data-cycle-action=prepare data-cycle-value=chapter>先继续第一章</button>':''}${c.stage==='explore'?'<button data-cycle-action=goals>选择攻略目标</button>':''}${c.primary.action!=='map'?'<button data-cycle-action=map>自由选择路线</button>':''}</div><small>已通关${c.cleared}/${c.total}条路线。目标是可跳过的探索指引，不是难度排名、培养门槛或额外任务奖励。</small></section>`;}
export function reportHandoffView(s,objective=''){return `<p class=eyebrow>战报来源 / 归营交接</p><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p>${objective}${s.receipt?`<p class=handoff-reward>${reward(s.receipt)}</p>`:''}<div class=bar>${s.status==='pending'?'<button class=primary data-report-cycle=claim>领取本次收益并归营</button>':s.status==='claimed'?'<button class=primary data-report-cycle=training>去查看我的成长</button>':s.status==='recorded'?'<button class=primary data-report-cycle=goals>回看攻略目标</button>':'<button class=primary data-report-cycle=official>回营核对正式出征</button>'}${s.otherPending?`<button data-report-cycle=pending>另有第${s.otherPending}次待结算 · 查看该次战报</button>`:''}<button data-report-cycle=camp>返回营地</button></div>`;}
